1 clause(s), 1 step(s), lemmas: compatible-map, compatible

clause ∘-is-hom ghom hhom
  goal: IsHom 𝑨 𝑪 (h ⟨∘⟩ g)
  1. IsHom 𝑨 𝑪 (h ⟨∘⟩ g)
       by mkhom c where c : compatible-map 𝑨 𝑪 (h ⟨∘⟩ g) c = trans (cong h (compatible ghom)) (compatible hhom)   [compatible-map, compatible]

